@charset "UTF-8";
.bill-grid {
  display: grid;
  grid-auto-flow: column; /* keep in single row */
  grid-auto-columns: 180px;
  gap: 24px; /* increased from 12px → 24px */
  background: var(--appsmith-theme-backgroundColor, #1E293A);
  padding: 0px;
  font-family: system-ui, sans-serif;
  overflow-x: auto;
  border-radius: 10px;
  white-space: nowrap;
}

.label-column {
  background: var(--appsmith-theme-backgroundColor, #1E293A);
  padding: 5px 10px;
}

.label-cell {
  margin: 12px 0;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  font-size: 14px;
  font-weight: 500;
}

.bill-card {
  background: var(--appsmith-theme-surfaceColor, #0f172a);
  border-radius: 8px;
  box-shadow: 0 0 4px rgba(0, 0, 0, 0.08);
  padding: 12px 8px;
  text-align: center;
  min-width: 180px;
  flex-shrink: 0;
}

.bill-title {
  font-weight: 700;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  margin-bottom: 8px;
  font-size: 15px;
}

.value-cell {
  padding: 10px 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  text-align: right;
}

.value-cell:nth-child(even) {
  background: var(--appsmith-theme-surfaceAltColor, #1e293b);
}

.value-cell:nth-child(odd) {
  background: var(--appsmith-theme-surfaceColor, #0f172a);
}

.value-cell a {
  color: var(--appsmith-theme-linkColor, #60a5fa);
  text-decoration: none;
}

.value-cell a:hover {
  text-decoration: underline;
}
/* Theme scrollbars (no bright default bars in dark) */
* { scrollbar-color: var(--appsmith-theme-borderColor, #334155) var(--appsmith-theme-surfaceColor, #0f172a); scrollbar-width: thin; }
::-webkit-scrollbar { width: 10px; height: 10px; background: var(--appsmith-theme-surfaceColor, #0f172a); }
::-webkit-scrollbar-thumb { background: var(--appsmith-theme-borderColor, #334155); border-radius: 5px; }
::-webkit-scrollbar-corner { background: var(--appsmith-theme-surfaceColor, #0f172a); }

body, #root { color: var(--appsmith-theme-textColor, #e2e8f0); font-family: system-ui, sans-serif; font-size: 14px; }

